# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::Handoff::CheckpointEntryValues do
  # entries.locked is nullable and never reaches a snapshot, so a NULL there
  # must not refuse a checkpoint. The rows go through the transport form so the
  # check sees the decoded values a load inserts (Integer, Date, Time, Float).
  it "returns no invalid entries for decoded checkpoint rows whose stored locked is NULL" do
    tables = merge_handoff_checkpoint_tables(
      handoff_checkpoint_tables(company_id: 8, id: 900, overrides: { "entries" => { "locked" => nil } }),
      handoff_checkpoint_tables(company_id: 9, id: 901,
                                overrides: { "entries" => { "source_metadata" => { "rate" => BigDecimal("1.5") } } })
    )
    rows = Timekeeping::Handoff::Checkpoint.from_json(Timekeeping::Handoff::Checkpoint.build(tables:).to_json)
      .rows.fetch("entries")

    expect(rows.first.fetch("locked")).to be_nil
    expect(described_class.invalid_entries(rows)).to eq([])
  end

  # "A monolith row with a source such as "agent" is therefore stored in Timekeeping's entries table, and any later write republishes it to the outbox, where the projection refuses it and delivery stops."
  it "names only the second checkpoint entry when its source is agent" do
    expect(Timekeeping::SnapshotValues::SOURCES).not_to include("agent")
    rows = handoff_checkpoint_tables(company_id: 8, id: 900).fetch("entries") +
           handoff_checkpoint_tables(company_id: 9, id: 901, overrides: { "entries" => { "source" => "agent" } })
             .fetch("entries")

    expect(described_class.invalid_entries(rows)).to eq([{ company_id: 9, id: 901, fields: ["source"] }])
  end

  # One item per bad row, in row order, each naming every invalid field in
  # SnapshotValues::RULES order with version last; a valid row between them is skipped.
  it "names every invalid row in row order with all of its invalid fields" do
    rows = [
      handoff_checkpoint_tables(company_id: 8, id: 900,
                                overrides: { "entries" => { "source" => "agent", "bill_status" => "paid",
                                                            "version" => 0 } }),
      handoff_checkpoint_tables(company_id: 8, id: 901),
      handoff_checkpoint_tables(company_id: 9, id: 902, overrides: { "entries" => { "review_status" => "done" } })
    ].flat_map { |tables| tables.fetch("entries") }

    expect(described_class.invalid_entries(rows)).to eq([
      { company_id: 8, id: 900, fields: %w[bill_status source version] },
      { company_id: 9, id: 902, fields: ["review_status"] }
    ])
  end

  # The projection refuses a non-positive version, an unknown status and a
  # duration JSON cannot carry; the checkpoint load is the only check before
  # write_outbox republishes them.
  it "names version, statuses and a non-finite duration on checkpoint entries but not a NULL locked" do
    refused = [
      ["version", 0], ["version", -1], ["bill_status", "paid"], ["review_status", "done"],
      ["duration", Float::INFINITY], ["duration", Float::NAN]
    ]

    refused.each_with_index do |(field, value), index|
      id = 900 + index
      row = handoff_checkpoint_tables(company_id: 8, id:,
                                      overrides: { "entries" => { field => value, "locked" => nil } }).fetch("entries")
      expect(described_class.invalid_entries(row))
        .to eq([{ company_id: 8, id:, fields: [field] }]), "expected #{field} = #{value.inspect} to be refused"
    end
  end

  # Plain rows, never Checkpoint.build: the checkpoint checksum cannot encode
  # metadata this deep, so the edges are only reachable on the pure check.
  it "accepts checkpoint entry metadata nested 96 levels and names 97" do
    nested = ->(levels) { levels.times.reduce("leaf") { |value, _| { "child" => value } } }

    %w[source_metadata proof_metadata].each do |field|
      at_limit = handoff_checkpoint_tables(company_id: 8, id: 900,
                                           overrides: { "entries" => { field => nested.call(96) } }).fetch("entries")
      too_deep = handoff_checkpoint_tables(company_id: 8, id: 901,
                                           overrides: { "entries" => { field => nested.call(97) } }).fetch("entries")

      expect(described_class.invalid_entries(at_limit)).to eq([])
      expect(described_class.invalid_entries(too_deep)).to eq([{ company_id: 8, id: 901, fields: [field] }])
    end
  end
end
